package ocrtest

import (
	"emon/ocr"
	"emon/port"
	"testing"
)

func TestTheResolutionHintIsTheFlagsAboveTheLowByte(emonT *testing.T) {
	port.AssertEq(emonT, ocr.OcfDpi(ocr.OcfSymbols()+ocr.OcfOsd()), 0, "no hint in the low flags")
	port.AssertEq(emonT, ocr.OcfDpi(3+(150*256)), 150, "150 dpi")
	port.AssertEq(emonT, ocr.OcfDpi(3+(300*256)), 300, "300 dpi")
}
